def install() -> None:
    base = Path("/tmp/_pyi_stubs")
    for package, text in STUBS.items():
        target = base / package.replace(".", "/")
        target.mkdir(parents=True, exist_ok=True)
        (target / "__init__.pyi").write_text(text)

    original = lazy_loader.attach_stub

    def attach_stub_with_fallback(package_name: str, filename: str):
        try:
            return original(package_name, filename)
        except ValueError:
            alt = base / package_name.replace(".", "/") / "__init__.py"
            return original(package_name, str(alt))

    lazy_loader.attach_stub = attach_stub_with_fallback
